import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.BbQrW5_t.js";const g=JSON.parse('{"title":"学习路线图","description":"","frontmatter":{"title":"学习路线图","date":"2026-09-03T00:00:00.000Z"},"headers":[],"relativePath":"study/cyber-security/00-学习路线图.md","filePath":"study/cyber-security/00-学习路线图.md","lastUpdated":null}'),l={name:"study/cyber-security/00-学习路线图.md"};function i(n,t,s,d,h,u){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="学习路线图-从工程师到攻防从业者" tabindex="-1">学习路线图：从工程师到攻防从业者 <a class="header-anchor" href="#学习路线图-从工程师到攻防从业者" aria-label="Permalink to &quot;学习路线图：从工程师到攻防从业者&quot;">​</a></h1><h2 id="你的起手优势-背景定制" tabindex="-1">你的起手优势（背景定制） <a class="header-anchor" href="#你的起手优势-背景定制" aria-label="Permalink to &quot;你的起手优势（背景定制）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>已有资产</th><th>攻防映射</th><th>策略</th></tr></thead><tbody><tr><td>20 年 Python/JS 全栈</td><td>代码审计、安全工具开发</td><td><strong>跳过编程课</strong>，直接学&quot;攻击者视角读代码&quot;</td></tr><tr><td>系统拆解与 Debug 能力</td><td>渗透测试方法论</td><td>你最强的迁移资产</td></tr><tr><td>AI 协作工作流</td><td>信息收集/报告自动化</td><td>用 AI 杠杆放大 2h/周的碎片时间</td></tr><tr><td>教师转型主线</td><td>费曼式输出</td><td>每篇笔记写成&quot;能教别人的教程&quot;，知识双倍固化</td></tr></tbody></table><h2 id="三年阶段设计" tabindex="-1">三年阶段设计 <a class="header-anchor" href="#三年阶段设计" aria-label="Permalink to &quot;三年阶段设计&quot;">​</a></h2><h3 id="第-1-年-·-筑基-打地基-首证" tabindex="-1">第 1 年 · 筑基（打地基 + 首证） <a class="header-anchor" href="#第-1-年-·-筑基-打地基-首证" aria-label="Permalink to &quot;第 1 年 · 筑基（打地基 + 首证）&quot;">​</a></h3><ul><li><strong>知识</strong>：TCP/IP 与抓包 → Linux → OWASP Top10 → Python 安全脚本 → 操作系统与域概念</li><li><strong>实践</strong>：DVWA、攻防世界新手区、TryHackMe、PicoCTF</li><li><strong>里程碑</strong>：NISP（国家注册信息安全专业人员）证书 + 首次 SRC 试水</li><li><strong>判断点</strong>：年末确认兴趣浓度，决定第 2 年主攻渗透（攻）还是蓝队（防）</li></ul><h3 id="第-2-年-·-实战-方法论-硬证书" tabindex="-1">第 2 年 · 实战（方法论 + 硬证书） <a class="header-anchor" href="#第-2-年-·-实战-方法论-硬证书" aria-label="Permalink to &quot;第 2 年 · 实战（方法论 + 硬证书）&quot;">​</a></h3><ul><li><strong>知识</strong>：PTES 渗透流程、内网与域渗透概念、代码审计（Java/PHP/Python Web）、应急响应、SIEM 告警研判</li><li><strong>实践</strong>：VulnHub 靶机、SRC 月更、护网蓝队（HW 季值班研判）</li><li><strong>里程碑</strong>：<strong>CISP-PTE</strong>（国内渗透测试入场券，护网认可度高）+ 3+ 个有效 SRC 漏洞</li><li><strong>判断点</strong>：护网体验后选择长线方向</li></ul><h3 id="第-3-年-·-专精-分化-国际认证-反哺教学" tabindex="-1">第 3 年 · 专精（分化 + 国际认证 + 反哺教学） <a class="header-anchor" href="#第-3-年-·-专精-分化-国际认证-反哺教学" aria-label="Permalink to &quot;第 3 年 · 专精（分化 + 国际认证 + 反哺教学）&quot;">​</a></h3><ul><li><strong>方向</strong>（三选一深化）：红队 / 漏洞研究 / 蓝队体系</li><li><strong>里程碑</strong>：OSCP（国际渗透认证）或 CISP 对应高阶 + 护网正式角色</li><li><strong>特色收官</strong>：「安全+编程」青少年选修课教案——把攻防变成你科技教师履历的差异化作品</li></ul><h2 id="时间账本" tabindex="-1">时间账本 <a class="header-anchor" href="#时间账本" aria-label="Permalink to &quot;时间账本&quot;">​</a></h2><p>每周 2h × 52 周 × 3 年 ≈ <strong>312 小时</strong>。策略：工作日 4×20min 碎片（读/看）+ 周末 1×60min（动手）。所有产出沉淀到本知识库，学习即创作。</p><h2 id="学习原则-写在前面防止跑偏" tabindex="-1">学习原则（写在前面防止跑偏） <a class="header-anchor" href="#学习原则-写在前面防止跑偏" aria-label="Permalink to &quot;学习原则（写在前面防止跑偏）&quot;">​</a></h2><ol><li><strong>靶场优先</strong>：所有动手在授权环境，法律红线见 <a href="./">总览</a></li><li><strong>输出倒逼输入</strong>：每周必须有一个&quot;产出&quot;（笔记/脚本/靶机报告）</li><li><strong>进度可视化</strong>：做完打勾，跑 <code>scripts/进度统计.py</code> 刷新面板</li><li><strong>允许降级</strong>：某周miss了→顺延，不内疚；连续 3 周miss→砍范围保节奏</li></ol>',14)])])}const _=a(l,[["render",i]]);export{g as __pageData,_ as default};
